src='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    positions = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                positions.setdefault(color, []).append((r, c))

    frames = []
    frame_cells = set()
    for color, cells in positions.items():
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r1 - r0 < 3 or c1 - c0 < 3:
            continue
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(cells) == border:
            frames.append((color, r0, r1, c0, c1, border))
            frame_cells |= border

    marker_counts = Counter()
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color and (r, c) not in frame_cells:
                marker_counts[color] += 1

    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1, border in frames:
        for r, c in border:
            out[r][c] = color
        needed = sum((r + c) % 2 == 0
                     for r in range(r0 + 1, r1) for c in range(c0 + 1, c1))
        fill = next((k for k, count in marker_counts.items() if count == needed), None)
        if fill is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == 0:
                        out[r][c] = fill
    return out
'''
